{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table rpsg_db.maplemonk.drv_product_ROAS as with GA4 as ( select date, upper(coalesce(channel,\'OTHERS\')) as channel, \'OTHERS\' as Category, upper(coalesce(Category,\'OTHERS\')) Product, sum(ifnull(sessions,0)) sessions, sum(ifnull(checkouts,0)) checkouts, sum(ifnull(addtocarts,0)) addtocarts from ( select sc.date, sc.source, sc.medium, sc.landingpage, sc.sessions, sc.checkouts, sc.addtocarts, coalesce(sc.channel,ga_mapping.New_Channel) as channel, Category from ( SELECT TO_DATE(date, \'YYYYMMDD\') Date, landingpage, SPLIT_PART(sessionsourcemedium, \'/\', 1) AS Source, CASE WHEN POSITION(\'/\' IN sessionsourcemedium) > 0 THEN SUBSTR(sessionsourcemedium, POSITION(\'/\' IN sessionsourcemedium) + 1) ELSE NULL END AS Medium, (case when lower(sessionsourcemedium) like \'%clickonik%\' then \'CLICKONIK\' end) as channel ,sum(ifnull(sessions,0)) as sessions ,sum(ifnull(addtocarts,0)) as addtocarts ,sum(ifnull(checkouts,0)) as checkouts FROM rpsg_db.maplemonk.ga4_drv_sessions__add_to_carts__landing_page group by 1,2,3,4,5 )sc left join ( select * from ( select source, Medium, \"New Channel\" as New_Channel, row_number() over(partition by lower(ifnull(source,\'\')),lower(ifnull(medium,\'\')) order by 1)rw, from rpsg_db.maplemonk.utm_ga_consolidated_channel_mapping )where rw=1 and (source is not null and medium is not null) )ga_mapping on REPLACE(LOWER(IFNULL(ga_mapping.source, \'\')), \' \', \'\') = REPLACE(LOWER(IFNULL(sc.source, \'\')), \' \', \'\') AND REPLACE(LOWER(IFNULL(ga_mapping.medium, \'\')), \' \', \'\') = REPLACE(LOWER(IFNULL(sc.medium, \'\')), \' \', \'\') left join ( select \"Landing Page\" LandingPage ,\"Product Category\" Category FROM rpsg_db.maplemonk.drv_landingpage_mapping qualify row_number() over(partition by lower(\"Landing Page\") order by 1) = 1 )lm on REPLACE(LOWER(IFNULL(sc.landingpage, \'\')), \' \', \'\') = REPLACE(LOWER(IFNULL(lm.landingpage, \'\')), \' \', \'\') ) group by 1,2,3,4 ), invoicedatemetrics as ( select try_to_date(FI.invoice_date) Invoice_Date ,upper(coalesce(category ,\'OTHERS\')) product_name_mapped ,upper(coalesce(report_category,\'OTHERS\')) category ,upper(FI.final_channel) Channel ,count(distinct order_id) Invoice_orders ,sum(ifnull((case when lower(order_status) not in (\'cancelled\') then ifnull(FI.SELLING_PRICE,0)-ifnull(FI.TAX,0) end),0)) Realised_Revenue ,sum(selling_price) total_Sales ,ifnull(sum(case when FI.return_flag=1 then ifnull(FI.SELLING_PRICE,0) end),0) as return_value_invoice_Date from RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_DRV FI where lower(marketplace) like any (\'%shopify%\', \'%woocommerce%\') and invoice_date !=\'\' group by 1,2,3,4 order by 1 desc ), returnsales as ( select return_date::date return_date ,upper(channel) channel ,upper(coalesce(category ,\'OTHERS\')) product ,upper(coalesce(report_category,\'OTHERS\')) category ,count(distinct reference_code) return_orders ,sum(ifnull(TOTAL_RETURN_AMOUNT,0)) TOTAL_RETURN_AMOUNT ,sum(ifnull(RETURN_AMOUNT_WITHOUT_TAX,0)) TOTAL_RETURN_AMOUNT_EXCL_TAX ,sum(ifnull(RETURNED_QUANTITY,0)) TOTAL_RETURNED_QUANTITY from RPSG_DB.MAPLEMONK.fact_items_easyecom_returns_detailed_drv rd where lower(company_name) like any (\'%herbolab%\',\'%dr vaidya%\') and lower(marketplace) like any (\'%shopify%\',\'%woocommerce%\') group by 1,2,3,4 order by 1 desc ), Delivered_Revenue as ( select coalesce(return_date,Invoice_Date) Invoice_Date ,case when upper(coalesce(ivm.channel,rs.channel)) = \'FB\' then \'FACEBOOK\' ELSE upper(coalesce(ivm.channel,rs.channel)) END as Channel ,coalesce(ivm.product_name_mapped,rs.product) as product_name_mapped ,coalesce(ivm.category,rs.category) category ,ifnull(ivm.Realised_Revenue,0)- ifnull(rs.TOTAL_RETURN_AMOUNT_EXCL_TAX,0) as Realised_Revenue ,ifnull(Invoice_orders,0) - ifnull(return_orders,0) as Delivered_Orders ,ifnull(total_sales,0) total_sales ,ifnull(return_value_invoice_Date,0) return_value_invoice_Date from invoicedatemetrics ivm full outer join returnsales rs on rs.return_date = ivm.Invoice_Date and lower(ivm.product_name_mapped) = lower(rs.product) and lower(ivm.category) = lower(rs.category) and lower(ivm.channel) = lower(rs.channel) where coalesce(return_date,Invoice_Date) >= \'2023-01-01\' ), Spends as ( Select date ,channel ,upper(product) as product ,upper(category) as category ,sum(ifnull(spend,0)) spend ,sum(ifnull(Clicks,0)) Clicks ,sum(ifnull(IMPRESSIONS,0)) IMPRESSIONS from rpsg_db.maplemonk.drv_marketing_product_spends where date >= \'2023-01-01\' group by 1,2,3,4 ) select coalesce(s.date,dr.Invoice_Date,g.date) date ,upper(coalesce(dr.product_name_mapped,s.product,g.product)) as product ,upper(coalesce(dr.category,S.category,g.category)) as category ,upper(coalesce(dr.channel,s.channel,g.channel)) as channel ,case when upper(coalesce(dr.channel,s.channel,g.channel)) = \'MOBLIGENT\' then (ifnull(total_sales,0)-ifnull(return_value_invoice_Date,0))/1.2 else s.spend end as spend ,Clicks ,IMPRESSIONS ,Delivered_Orders ,Realised_Revenue ,sessions ,addtocarts ,checkouts from Delivered_Revenue dr full outer join Spends s on s.date = dr.Invoice_Date and lower(dr.product_name_mapped) = lower(ifnull(s.product,\'a\')) and lower(dr.category) = lower(ifnull(s.category,\'a\')) and lower(dr.channel) = lower(ifnull(s.channel,\'a\')) full outer join GA4 g on coalesce(dr.Invoice_Date,s.date) = g.date and coalesce(lower(dr.product_name_mapped),lower(s.product)) = lower(g.product) and coalesce(lower(dr.category),lower(s.category)) = lower(g.category) and coalesce(lower(dr.channel),lower(s.channel)) = lower(g.channel) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RPSG_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            